	var filesTouched []string
	if sameSessionStore {
		adopted, filesTouched, err = adoptFromSameSessionStore(ctx, sourceWorktree, sourceState, opts)
	} else {
		adopted, filesTouched, err = adoptFromExternalSessionStore(
			ctx,
			sourceStore,
			sourceWorktree,
			sourceCommonDir,
			targetStore,
			targetCommonDir,
			sourceState.SessionID,
			opts,
		)
	}
