func validateAdoptSourceTranscript(source *session.State, sourceWorktree string) error {
	if source == nil || strings.TrimSpace(source.TranscriptPath) == "" {
		return nil
	}

	owner, ok := agent.AgentForTranscriptPath(source.TranscriptPath, sourceWorktree)
	if !ok {
		return fmt.Errorf("unexpected transcript path for session %s: %s is not owned by a registered agent for %s",
			source.SessionID, source.TranscriptPath, sourceWorktree)
	}
	if source.AgentType != "" && owner.Type() != source.AgentType {
		return fmt.Errorf("unexpected transcript path for session %s: %s belongs to %s, but source state says %s",
			source.SessionID, source.TranscriptPath, owner.Type(), source.AgentType)
	}
	return nil
}

func stateStoreForWorktree(ctx context.Context, worktreePath string) (*session.StateStore, string, string, error) {
	absWorktree, err := filepath.Abs(worktreePath)
	if err != nil {
		return nil, "", "", fmt.Errorf("resolve source worktree: %w", err)
	}

	cmd := exec.CommandContext(ctx, "git", "-C", absWorktree, "rev-parse", "--show-toplevel", "--git-common-dir")
	var stderr bytes.Buffer
	cmd.Stderr = &stderr
	output, err := cmd.Output()
	if err != nil {
		msg := strings.TrimSpace(stderr.String())
		if msg != "" {
			return nil, "", "", fmt.Errorf("resolve source git directory: %s: %w", msg, err)
		}
		return nil, "", "", fmt.Errorf("resolve source git directory: %w", err)
	}

	lines := strings.Split(strings.TrimSpace(string(output)), "\n")
	if len(lines) < 2 {
		return nil, "", "", fmt.Errorf("resolve source git directory: unexpected git output %q", strings.TrimSpace(string(output)))
	}
	sourceRoot := strings.TrimSpace(lines[0])
	commonDir := strings.TrimSpace(lines[1])
	if !filepath.IsAbs(commonDir) {
		commonDir = filepath.Join(absWorktree, commonDir)
	}
	commonDir = filepath.Clean(commonDir)

	return session.NewStateStoreWithDir(filepath.Join(commonDir, session.SessionStateDirName)), sourceRoot, commonDir, nil
}

func selectAdoptSourceSession(ctx context.Context, store *session.StateStore, sourceWorktree, sessionID string) (*session.State, error) {
	sourceWorktreeID, worktreeIDErr := paths.GetWorktreeID(sourceWorktree)
	if worktreeIDErr != nil {
		sourceWorktreeID = ""
	}
	if sessionID != "" {
		sourceState, err := store.Load(ctx, sessionID)
		if err != nil {
			return nil, fmt.Errorf("load source session state: %w", err)
		}
		if sourceState == nil {
			return nil, fmt.Errorf("session %s was not found in %s", sessionID, sourceWorktree)
		}
		if !isAdoptableSourceSession(sourceState) {
			return nil, fmt.Errorf("session %s is ended or fully condensed and cannot be adopted", sessionID)
		}
		if !sessionBelongsToSourceWorktree(sourceState, sourceWorktree, sourceWorktreeID) {
			return nil, fmt.Errorf("session %s belongs to %s, not %s",
				sessionID, adoptSessionWorktreeLabel(sourceState), sourceWorktree)
		}
		return sourceState, nil
	}

	states, err := store.List(ctx)
	if err != nil {
		return nil, fmt.Errorf("list source sessions: %w", err)
	}
	candidates := make([]*session.State, 0, len(states))
	for _, state := range states {
		if isRecentAdoptCandidate(state) && sessionBelongsToSourceWorktree(state, sourceWorktree, sourceWorktreeID) {
			candidates = append(candidates, state)
		}
	}
	sort.Slice(candidates, func(i, j int) bool {
		return sessionLastSeen(candidates[i]).After(sessionLastSeen(candidates[j]))
	})

	switch len(candidates) {
	case 0:
		return nil, fmt.Errorf("no recent active sessions found in %s", sourceWorktree)
	case 1:
		return candidates[0], nil
	default:
		ids := make([]string, 0, len(candidates))
		for _, candidate := range candidates {
			ids = append(ids, candidate.SessionID)
		}
		return nil, fmt.Errorf("multiple recent active sessions found in %s; pass one of: %s",
			sourceWorktree, strings.Join(ids, ", "))
	}
}

func sessionBelongsToSourceWorktree(state *session.State, sourceWorktree, sourceWorktreeID string) bool {
	if state == nil {
		return false
	}
	if state.WorktreeID != "" && sourceWorktreeID != "" {
		return state.WorktreeID == sourceWorktreeID
	}
	if state.WorktreePath != "" {
		return sameAdoptPath(state.WorktreePath, sourceWorktree)
	}
	return false
}

func adoptSessionWorktreeLabel(state *session.State) string {
	if state == nil {
		return unknownPlaceholder
	}
	if state.WorktreePath != "" {
		return state.WorktreePath
	}
	if state.WorktreeID != "" {
		return state.WorktreeID
	}
	return unknownPlaceholder
}

func isRecentAdoptCandidate(state *session.State) bool {
	if !isAdoptableSourceSession(state) {
		return false
	}
	lastSeen := sessionLastSeen(state)
	if lastSeen.IsZero() {
		return false
	}
	return time.Since(lastSeen) <= adoptRecentWindow
}

func isAdoptableSourceSession(state *session.State) bool {
	return state != nil &&
		state.Phase != session.PhaseEnded &&
		state.EndedAt == nil &&
		!state.FullyCondensed
}

func sessionLastSeen(state *session.State) time.Time {
	if state.LastInteractionTime != nil {
		return *state.LastInteractionTime
	}
	return state.StartedAt
}

func buildAdoptedSessionState(ctx context.Context, source *session.State) (*session.State, []string, error) {
	repo, err := openRepository(ctx)
	if err != nil {
		return nil, nil, fmt.Errorf("open current repository: %w", err)
	}
	defer repo.Close()

	head, err := repo.Head()
	if err != nil {
		return nil, nil, fmt.Errorf("resolve current HEAD: %w", err)
	}

	worktreeRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return nil, nil, fmt.Errorf("resolve current worktree root: %w", err)
	}
	worktreeID, err := paths.GetWorktreeID(worktreeRoot)
	if err != nil {
		return nil, nil, fmt.Errorf("resolve current worktree ID: %w", err)
	}

	branch, branchErr := GetCurrentBranch(ctx)
	if branchErr != nil {
		branch = ""
	}
	filesTouched, err := currentFilesTouched(ctx)
	if err != nil {
		return nil, nil, err
	}
	untrackedFiles, err := strategy.CollectUntrackedFiles(ctx)
	if err != nil {
		untrackedFiles = nil
	}

	now := time.Now()
	adopted := cloneAdoptSourceState(source)

	// Keep the source live transcript path. In cross-repo adoption the transcript
	// belongs to the continuing agent session, not the target repository; clearing
	// or recomputing it from the target repo would drop live transcript capture.
	adopted.CLIVersion = versioninfo.Version
	adopted.TranscriptPath = source.TranscriptPath
	adopted.BaseCommit = head.Hash().String()
	adopted.RealignAttributionBase(head.Hash().String())
	adopted.WorktreePath = worktreeRoot
	adopted.WorktreeID = worktreeID
	adopted.AdoptedIntoWorktreePath = ""
	adopted.AdoptedIntoWorktreeID = ""
	adopted.Branch = branch
	adopted.LastInteractionTime = &now
	adopted.Phase = session.PhaseActive
	adopted.EndedAt = nil
	adopted.FilesTouched = filesTouched

	// Reset target-local checkpoint bookkeeping. Source checkpoint IDs can point
	// at metadata in another repository or checkpoint branch; carrying them into
	// this repo would let amend and turn-finalization paths operate on unrelated
	// checkpoints.
	adopted.StepCount = 0
	adopted.CheckpointTranscriptStart = 0
	adopted.CheckpointTranscriptSize = 0
	adopted.TranscriptIdentifierAtStart = ""
	adopted.ClearLegacyTranscriptOffsets()
	adopted.TurnID = ""
	adopted.TurnCheckpointIDs = nil
	adopted.LastCheckpointID = id.EmptyCheckpointID
	adopted.ClearCondensationAttempt()
	adopted.LastCheckpointCommitHash = ""
	adopted.CheckpointTokenUsage = nil
	// Re-baseline the subagent cumulative for the fresh target-local window. The
	// cloned TokenUsage carries the SOURCE session's full cumulative subagent
	// total; without re-baselining here, the first post-adopt checkpoint would
	// subtract the source's (stale or nil) baseline and over-report — potentially
	// the source session's entire subagent usage. Mirrors resetCheckpointWindow's
	// baseline capture so the first adopted checkpoint only counts target-side
	// subagent growth, consistent with the PromptWindowBase reset below.
	adopted.RebaselineSubagentTokens()

	adopted.FullyCondensed = false
	adopted.UntrackedFilesAtStart = untrackedFiles
	adopted.PromptAttributions = nil
	adopted.PendingPromptAttribution = nil
	// Preserve cumulative turn/context metrics for the continuing agent session,
	// but start the target checkpoint prompt window at the current turn count so
	// the first adopted checkpoint only counts target-side turns.
	adopted.PromptWindowBase = adopted.SessionTurnCount
	adopted.PromptWindowResetPending = false
	adopted.AttachedManually = false
	// The source process owner may already be gone; a new turn will capture the
	// current owner, and until then liveness should fall back to the timeout.
	adopted.Owner = nil

	return &adopted, filesTouched, nil
}

func cloneAdoptSourceState(source *session.State) session.State {
	adopted := *source
	adopted.EndedAt = cloneTimePtr(source.EndedAt)
	adopted.LastInteractionTime = cloneTimePtr(source.LastInteractionTime)
	adopted.ReviewSkills = slices.Clone(source.ReviewSkills)
	adopted.TurnCheckpointIDs = slices.Clone(source.TurnCheckpointIDs)
	adopted.UntrackedFilesAtStart = slices.Clone(source.UntrackedFilesAtStart)
	adopted.FilesTouched = slices.Clone(source.FilesTouched)
	adopted.TokenUsage = cloneTokenUsage(source.TokenUsage)
	adopted.SkillEvents = cloneSkillEvents(source.SkillEvents)
	adopted.PromptAttributions = clonePromptAttributions(source.PromptAttributions)
	if source.PendingPromptAttribution != nil {
		pending := clonePromptAttribution(*source.PendingPromptAttribution)
		adopted.PendingPromptAttribution = &pending
	}
	return adopted
}

func cloneTimePtr(t *time.Time) *time.Time {
	if t == nil {
		return nil
	}
	cloned := *t
	return &cloned
}

func cloneTokenUsage(usage *agent.TokenUsage) *agent.TokenUsage {
	if usage == nil {
		return nil
	}
	cloned := *usage
		if agErr != nil {
			fmt.Fprintf(errW, "  Warning: session %d (%s) has unknown agent %q, skipping\n", i, sessionID, content.Metadata.Agent)
			continue
		}

		// Compute transcript path from current repo location for cross-machine portability.
		sessionAgentDir, dirErr := sessionAgent.GetSessionDir(repoRoot)
		if dirErr != nil {
			fmt.Fprintf(errW, "  Warning: failed to get session dir for session %d: %v\n", i, dirErr)
			continue
		}
		restoreStore, storeErr := agent.OpenSessionStoreAt(sessionAgent, sessionAgentDir)
		if storeErr != nil {
			fmt.Fprintf(errW, "  Warning: failed to open session store for session %d: %v\n", i, storeErr)
			continue
		}
		_, sessionFile, resolveErr := restoreStore.SessionFile(sessionID)
		if resolveErr != nil {
			fmt.Fprintf(errW, "  Warning: session %d (%s) resolves outside its session directory, skipping\n", i, sessionID)
			continue
		}
		if resolver, ok := sessionAgent.(agent.RestoredSessionPathResolver); ok {
			resolvedFile, resolveErr := resolver.ResolveRestoredSessionFile(sessionAgentDir, sessionID, content.Transcript)
			if resolveErr != nil {
				fmt.Fprintf(errW, "  Warning: failed to resolve restored session path for session %d (%s): %v (using fallback path)\n", i, sessionID, resolveErr)
			} else {
				sessionFile = resolvedFile
			}
		}

		promptPreview := restoredPromptPreview(sessionAgent, content.Prompts, content.Transcript, content.Metadata.ReviewPrompt)

		// Local log already present and not forcing: keep it untouched, but still
		// report the session so the caller can print its resume command.
		if skipExisting[sessionID] {
			if totalSessions > 1 {
				fmt.Fprintf(w, "  Session %d: keeping existing local log\n", i+1)
			} else {
				fmt.Fprintf(w, "Keeping existing local session log\n")
			}
			restored = append(restored, RestoredSession{
				SessionID:    sessionID,
				CheckpointID: point.CheckpointID.String(),
				Agent:        sessionAgent.Type(),
				Prompt:       promptPreview,
				CreatedAt:    content.Metadata.CreatedAt,
				Kind:         content.Metadata.Kind,
				ReviewPrompt: content.Metadata.ReviewPrompt,
			})
			continue
		}

		if totalSessions > 1 {
			isLatest := i == totalSessions-1
			if promptPreview != "" {
				if isLatest {
					fmt.Fprintf(w, "  Session %d (latest): %s\n", i+1, promptPreview)
				} else {
					fmt.Fprintf(w, "  Session %d: %s\n", i+1, promptPreview)
				}
			}
			fmt.Fprintf(w, "    Writing to: %s\n", sessionFile)
		} else {
			fmt.Fprintf(w, "Writing transcript to: %s\n", sessionFile)
		}

		// No MkdirAll here: WriteSession routes through agent.WriteSessionFile,
		// which creates the parent as part of the write. That matters because a
		// RestoredSessionPathResolver may have moved sessionFile to a sibling
		// directory that does not exist yet.
		agentSession := &agent.AgentSession{
			SessionID:  sessionID,
			AgentName:  sessionAgent.Name(),
			RepoPath:   repoRoot,
			SessionRef: sessionFile,
			NativeData: content.Transcript,
		}
		if writeErr := sessionAgent.WriteSession(ctx, agentSession); writeErr != nil {
			if totalSessions > 1 {
				fmt.Fprintf(errW, "    Warning: failed to write session: %v\n", writeErr)
				continue
			}
			return nil, fmt.Errorf("failed to write session: %w", writeErr)
		}

		restored = append(restored, RestoredSession{
			SessionID:    sessionID,
			CheckpointID: point.CheckpointID.String(),
			Agent:        sessionAgent.Type(),
			Prompt:       promptPreview,
			CreatedAt:    content.Metadata.CreatedAt,
			Kind:         content.Metadata.Kind,
			ReviewPrompt: content.Metadata.ReviewPrompt,
		})
	}

	return restored, nil
}

func restoredPromptPreview(sessionAgent agent.Agent, promptContent string, transcript []byte, reviewPrompt string) string {
	if prompt := ExtractFirstPrompt(promptContent); prompt != "" {
		return prompt
	}
	if prompt := strings.TrimSpace(reviewPrompt); prompt != "" {
		return prompt
	}
	extractor, ok := sessionAgent.(agent.PromptExtractor)
	if !ok || len(transcript) == 0 {
		return ""
	}
	prompts, err := extractPromptsFromTranscriptBytes(extractor, transcript)
	if err != nil || len(prompts) == 0 {
		return ""
	}
	if first := FirstDisplayPrompt(prompts); first != "" {
		return TruncateDescription(first, MaxDescriptionLength)
	}
	return ""
}

// FirstDisplayPrompt returns the first prompt in the list worth showing as a
// title/preview: the first entry that is non-empty, not separator-only, and not
// agent-injected (runtime preambles, AGENTS.md dumps — see
// textutil.IsInjectedPrompt). Returns "" if none qualifies, which callers that
// must show something should treat as "fall back to the raw first prompt".
//
// The returned text is not truncated; callers that render it into a fixed-width
// display are responsible for that (see restoredPromptPreview).
func FirstDisplayPrompt(prompts []string) string {
	for _, prompt := range prompts {
		cleaned := strings.TrimSpace(prompt)
		if cleaned == "" || isOnlySeparators(cleaned) || textutil.IsInjectedPrompt(cleaned) {
			continue
		}
		return cleaned
	}
	return ""
}

func extractPromptsFromTranscriptBytes(extractor agent.PromptExtractor, transcript []byte) ([]string, error) {
	tmp, err := os.CreateTemp("", "entire-restored-transcript-*.jsonl")
	if err != nil {
		return nil, fmt.Errorf("create temporary transcript: %w", err)
	}
	tmpPath := tmp.Name()
	defer os.Remove(tmpPath)

	if _, err := tmp.Write(transcript); err != nil {
		_ = tmp.Close()
		return nil, fmt.Errorf("write temporary transcript: %w", err)
	}
	if err := tmp.Close(); err != nil {
		return nil, fmt.Errorf("close temporary transcript: %w", err)
	}
	prompts, err := extractor.ExtractPrompts(tmpPath, 0)
	if err != nil {
		return nil, fmt.Errorf("extract prompts from temporary transcript: %w", err)
	}
	return prompts, nil
}

// ResolveAgentForResume resolves the agent from checkpoint metadata.
func ResolveAgentForResume(agentType types.AgentType) (agent.Agent, error) {
	ag, err := agent.GetByAgentType(agentType)
	if err != nil {
		return nil, fmt.Errorf("resolving agent %q: %w", agentType, err)

	return sessions, nil
}

// displayRestoredSessions sorts sessions by CreatedAt and prints resume commands.
func displayRestoredSessions(w io.Writer, sessions []strategy.RestoredSession) error {
	sort.SliceStable(sessions, func(i, j int) bool {
		return sessions[i].CreatedAt.Before(sessions[j].CreatedAt)
	})

	if len(sessions) > 1 {
		fmt.Fprintf(w, "\n✓ Restored %d sessions. To continue:\n", len(sessions))
	} else if len(sessions) == 1 {
		fmt.Fprintf(w, "✓ Restored session %s.\n", sessions[0].SessionID)
		fmt.Fprintf(w, "\nTo continue this session:\n")
	}

	isMulti := len(sessions) > 1
	for i, sess := range sessions {
		sessionAgent, err := strategy.ResolveAgentForResume(sess.Agent)
		if err != nil {
			return fmt.Errorf("failed to resolve agent for session %s: %w", sess.SessionID, err)
		}
		printSessionCommand(w, sessionAgent.FormatResumeCommand(sess.SessionID), sess.Prompt, isMulti, i == len(sessions)-1)
	}

	return nil
}

func restoreSingleSession(ctx context.Context, w io.Writer, ag agent.Agent, sessionID string, checkpointID id.CheckpointID, repoRoot string, force bool) (strategy.RestoredSession, bool, error) {
	restored := strategy.RestoredSession{
		SessionID:    sessionID,
		CheckpointID: checkpointID.String(),
		Agent:        ag.Type(),
	}

	sessionLogPath, err := resolveTranscriptPath(ctx, sessionID, ag)
	if err != nil {
		return strategy.RestoredSession{}, false, fmt.Errorf("failed to resolve transcript path: %w", err)
	}

	if checkpointID.IsEmpty() {
		logging.Debug(ctx, "resume session: empty checkpoint ID",
			slog.String("checkpoint_id", checkpointID.String()),
		)
		return unavailableSessionLogResult(w, ag, restored, sessionLogPath, force)
	}

	repo, repoErr := openRepository(ctx)
	if repoErr != nil {
		return strategy.RestoredSession{}, false, fmt.Errorf("failed to open repository: %w", repoErr)
	}
	defer repo.Close()
	stores, err := checkpoint.Open(ctx, repo, checkpoint.OpenOptions{BlobFetcher: FetchBlobsByHash, RefFetcher: FetchCheckpointRef, ReadRemotes: strategy.CheckpointReadRemotes(ctx)})
	if err != nil {
		return strategy.RestoredSession{}, false, fmt.Errorf("open checkpoint store: %w", err)
	}
	logContent, _, err := checkpoint.ReadRawSessionLogForCheckpoint(ctx, stores.Persistent, checkpointID)
	if err != nil {
		if errors.Is(err, checkpoint.ErrCheckpointNotFound) || errors.Is(err, checkpoint.ErrNoTranscript) {
			logging.Debug(ctx, "resume session completed (no metadata)",
				slog.String("checkpoint_id", checkpointID.String()),
				slog.String("session_id", sessionID),
			)
			return unavailableSessionLogResult(w, ag, restored, sessionLogPath, force)
		}
		logging.Error(ctx, "resume session failed",
			slog.String("checkpoint_id", checkpointID.String()),
			slog.String("session_id", sessionID),
			slog.String("error", err.Error()),
		)
		return strategy.RestoredSession{}, false, fmt.Errorf("failed to get session log: %w", err)
	}

	// By default, never overwrite a session log that already exists locally: the
	// on-disk transcript is the live session the user is resuming, so we keep it
	// and just print the resume command. --force overwrites it from the checkpoint.
	if !force && sessionLogExists(ag, repoRoot, sessionLogPath) {
		fmt.Fprintf(w, "Keeping existing local session log for '%s' (use --force to overwrite from checkpoint).\n", sessionID)
		return restored, true, nil
	}

	// No MkdirAll here: WriteSession routes through agent.WriteSessionFile,
	// which creates the parent as part of the write.

	agentSession := &agent.AgentSession{
		SessionID:  sessionID,
		AgentName:  ag.Name(),
		RepoPath:   repoRoot,
		SessionRef: sessionLogPath,
		NativeData: logContent,
	}

	// Write the session using the agent's WriteSession method
	if err := ag.WriteSession(ctx, agentSession); err != nil {
		logging.Error(ctx, "resume session failed during write",
			slog.String("checkpoint_id", checkpointID.String()),
			slog.String("session_id", sessionID),
			slog.String("error", err.Error()),
		)
		return strategy.RestoredSession{}, false, fmt.Errorf("failed to write session: %w", err)
	}

	logging.Debug(ctx, "resume session completed",
		slog.String("checkpoint_id", checkpointID.String()),
		slog.String("session_id", sessionID),
	)

	fmt.Fprintf(w, "✓ Session restored to: %s\n", sessionLogPath)
	fmt.Fprintf(w, "  Session: %s\n", sessionID)

83fc621ff Use Equal for every plumbing.Hash comparison, and guard it
The first commit changed only the call site the original finding named and left seven others, one of them 45 lines above it in the same function — so a comment explaining why == is wrong sat just below a == doing the same thing. All eight now use Equal.

Adds a source guard rather than a test, because no test can distinguish the two operators. Checked against the pinned go-git: NewHash, FromHex, ResetBySize and Hasher.Sum all leave the object-format field unset for a 40-char hash and stamp "sha256" only on a 64-char one, so two hashes of the same object in one repository always carry the same format and == cannot disagree with Equal. The mismatch is unconstructible through the public API, which means a reverted call site stays green no matter what is asserted. TestHashComparisonsUseEqual pins the convention where it is written instead, and was verified by reverting content_overlap.go:497 and watching it fail.

That also answers the review note on the previous commit: the autocrlf regression does not pin this, and cannot. It passes with either operator.

Follow-up to #2336; resolves findings on trails 1277 and 1305.

