func restoredPromptPreview(sessionAgent agent.Agent, promptContent string, transcript []byte, reviewPrompt string) string {
	if prompt := ExtractFirstPrompt(promptContent); prompt != "" {
		return prompt
	}
	if prompt := strings.TrimSpace(reviewPrompt); prompt != "" {
		return prompt
	}
	extractor, ok := sessionAgent.(agent.PromptExtractor)
	if !ok || len(transcript) == 0 {
		return ""
	}
	prompts, err := extractPromptsFromTranscriptBytes(extractor, transcript)
	if err != nil || len(prompts) == 0 {
		return ""
	}
	if first := FirstDisplayPrompt(prompts); first != "" {
		return TruncateDescription(first, MaxDescriptionLength)
	}
	return ""
}

// FirstDisplayPrompt returns the first prompt in the list worth showing as a
// title/preview: the first entry that is non-empty, not separator-only, and not
// agent-injected (runtime preambles, AGENTS.md dumps — see
// textutil.IsInjectedPrompt). Returns "" if none qualifies, which callers that
// must show something should treat as "fall back to the raw first prompt".
//
// The returned text is not truncated; callers that render it into a fixed-width
// display are responsible for that (see restoredPromptPreview).
func FirstDisplayPrompt(prompts []string) string {
	for _, prompt := range prompts {
		cleaned := strings.TrimSpace(prompt)
		if cleaned == "" || isOnlySeparators(cleaned) || textutil.IsInjectedPrompt(cleaned) {
			continue
		}
		return cleaned
	}
	return ""
}

func extractPromptsFromTranscriptBytes(extractor agent.PromptExtractor, transcript []byte) ([]string, error) {
	tmp, err := os.CreateTemp("", "entire-restored-transcript-*.jsonl")
	if err != nil {
		return nil, fmt.Errorf("create temporary transcript: %w", err)
	}
	tmpPath := tmp.Name()
	defer os.Remove(tmpPath)

	if _, err := tmp.Write(transcript); err != nil {
		_ = tmp.Close()
		return nil, fmt.Errorf("write temporary transcript: %w", err)
	}
	if err := tmp.Close(); err != nil {
		return nil, fmt.Errorf("close temporary transcript: %w", err)
	}
	prompts, err := extractor.ExtractPrompts(tmpPath, 0)
	if err != nil {
		return nil, fmt.Errorf("extract prompts from temporary transcript: %w", err)
	}
	return prompts, nil
}

// ResolveAgentForResume resolves the agent from checkpoint metadata.
func ResolveAgentForResume(agentType types.AgentType) (agent.Agent, error) {
	ag, err := agent.GetByAgentType(agentType)
	if err != nil {
		return nil, fmt.Errorf("resolving agent %q: %w", agentType, err)

	return sessions, nil
}

// displayRestoredSessions sorts sessions by CreatedAt and prints resume commands.
func displayRestoredSessions(w io.Writer, sessions []strategy.RestoredSession) error {
	sort.SliceStable(sessions, func(i, j int) bool {
		return sessions[i].CreatedAt.Before(sessions[j].CreatedAt)
	})

	if len(sessions) > 1 {
		fmt.Fprintf(w, "\n✓ Restored %d sessions. To continue:\n", len(sessions))
	} else if len(sessions) == 1 {
		fmt.Fprintf(w, "✓ Restored session %s.\n", sessions[0].SessionID)
		fmt.Fprintf(w, "\nTo continue this session:\n")
	}

	isMulti := len(sessions) > 1
	for i, sess := range sessions {
		sessionAgent, err := strategy.ResolveAgentForResume(sess.Agent)
		if err != nil {
			return fmt.Errorf("failed to resolve agent for session %s: %w", sess.SessionID, err)
		}
		printSessionCommand(w, sessionAgent.FormatResumeCommand(sess.SessionID), sess.Prompt, isMulti, i == len(sessions)-1)
	}

	return nil
}

func restoreSingleSession(ctx context.Context, w io.Writer, ag agent.Agent, sessionID string, checkpointID id.CheckpointID, repoRoot string, force bool) (strategy.RestoredSession, bool, error) {
	restored := strategy.RestoredSession{
		SessionID:    sessionID,
		CheckpointID: checkpointID.String(),
		Agent:        ag.Type(),
	}

	sessionLogPath, err := resolveTranscriptPath(ctx, sessionID, ag)
	if err != nil {
		return strategy.RestoredSession{}, false, fmt.Errorf("failed to resolve transcript path: %w", err)
	}

	if checkpointID.IsEmpty() {
		logging.Debug(ctx, "resume session: empty checkpoint ID",
			slog.String("checkpoint_id", checkpointID.String()),
		)
		return unavailableSessionLogResult(w, ag, restored, sessionLogPath, force)
	}

	repo, repoErr := openRepository(ctx)
	if repoErr != nil {
		return strategy.RestoredSession{}, false, fmt.Errorf("failed to open repository: %w", repoErr)
	}
	defer repo.Close()
	stores, err := checkpoint.Open(ctx, repo, checkpoint.OpenOptions{BlobFetcher: FetchBlobsByHash, RefFetcher: FetchCheckpointRef, ReadRemotes: strategy.CheckpointReadRemotes(ctx)})
	if err != nil {
		return strategy.RestoredSession{}, false, fmt.Errorf("open checkpoint store: %w", err)
	}
	logContent, _, err := checkpoint.ReadRawSessionLogForCheckpoint(ctx, stores.Persistent, checkpointID)
	if err != nil {
		if errors.Is(err, checkpoint.ErrCheckpointNotFound) || errors.Is(err, checkpoint.ErrNoTranscript) {
			logging.Debug(ctx, "resume session completed (no metadata)",
				slog.String("checkpoint_id", checkpointID.String()),
				slog.String("session_id", sessionID),
			)
			return unavailableSessionLogResult(w, ag, restored, sessionLogPath, force)
		}
		logging.Error(ctx, "resume session failed",
			slog.String("checkpoint_id", checkpointID.String()),
			slog.String("session_id", sessionID),
			slog.String("error", err.Error()),
		)
		return strategy.RestoredSession{}, false, fmt.Errorf("failed to get session log: %w", err)
	}

	// By default, never overwrite a session log that already exists locally: the
	// on-disk transcript is the live session the user is resuming, so we keep it
	// and just print the resume command. --force overwrites it from the checkpoint.
	if !force && sessionLogExists(ag, repoRoot, sessionLogPath) {
		fmt.Fprintf(w, "Keeping existing local session log for '%s' (use --force to overwrite from checkpoint).\n", sessionID)
		return restored, true, nil
	}

	// No MkdirAll here: WriteSession routes through agent.WriteSessionFile,
	// which creates the parent as part of the write.

	agentSession := &agent.AgentSession{
		SessionID:  sessionID,
		AgentName:  ag.Name(),
		RepoPath:   repoRoot,
		SessionRef: sessionLogPath,
		NativeData: logContent,
	}

	// Write the session using the agent's WriteSession method
	if err := ag.WriteSession(ctx, agentSession); err != nil {
		logging.Error(ctx, "resume session failed during write",
			slog.String("checkpoint_id", checkpointID.String()),
			slog.String("session_id", sessionID),
			slog.String("error", err.Error()),
		)
		return strategy.RestoredSession{}, false, fmt.Errorf("failed to write session: %w", err)
	}

	logging.Debug(ctx, "resume session completed",
		slog.String("checkpoint_id", checkpointID.String()),
		slog.String("session_id", sessionID),
	)

	fmt.Fprintf(w, "✓ Session restored to: %s\n", sessionLogPath)
	fmt.Fprintf(w, "  Session: %s\n", sessionID)

83fc621ff Use Equal for every plumbing.Hash comparison, and guard it
The first commit changed only the call site the original finding named and left seven others, one of them 45 lines above it in the same function — so a comment explaining why == is wrong sat just below a == doing the same thing. All eight now use Equal.

Adds a source guard rather than a test, because no test can distinguish the two operators. Checked against the pinned go-git: NewHash, FromHex, ResetBySize and Hasher.Sum all leave the object-format field unset for a 40-char hash and stamp "sha256" only on a 64-char one, so two hashes of the same object in one repository always carry the same format and == cannot disagree with Equal. The mismatch is unconstructible through the public API, which means a reverted call site stays green no matter what is asserted. TestHashComparisonsUseEqual pins the convention where it is written instead, and was verified by reverting content_overlap.go:497 and watching it fail.

That also answers the review note on the previous commit: the autocrlf regression does not pin this, and cannot. It passes with either operator.

