 "github.com/entireio/cli/cmd/entire/cli/testutil"
)

func TestAuditInteractiveSettingsScope(t *testing.T) {
 setupTestRepo(t)
 t.Setenv("ENTIRE_TEST_CLAUDE_PROJECT_DIR", t.TempDir())
 writeSettings(t, `{"enabled":true,"log_level":"warn"}`)
 writeLocalSettings(t, `{"log_level":"debug"}`)
 ag, err := agent.Get(types.AgentName("claude-code")); if err != nil { t.Fatal(err) }
 var out bytes.Buffer
 err = runEnableInteractive(t.Context(), &out, []agent.Agent{ag}, EnableOptions{Yes:true, UseProjectSettings:true})
 if err != nil { t.Fatal(err) }
 got, err := settings.LoadFromFile(EntireSettingsFile); if err != nil { t.Fatal(err) }
 if got.LogLevel != "warn" { t.Fatalf("project log_level overwritten with local value: got %q; want warn", got.LogLevel) }
}

func TestAuditInteractiveMalformedSettings(t *testing.T) {
 setupTestRepo(t)
 t.Setenv("ENTIRE_TEST_CLAUDE_PROJECT_DIR", t.TempDir())
 original := `{"enabled":false,"log_level":"debug","future_setting":42}`
 writeSettings(t, original)
 ag, err := agent.Get(types.AgentName("claude-code")); if err != nil { t.Fatal(err) }
 var out bytes.Buffer
 enableErr := runEnableInteractive(t.Context(), &out, []agent.Agent{ag}, EnableOptions{Yes:true, UseProjectSettings:true})
 got, err := os.ReadFile(EntireSettingsFile); if err != nil { t.Fatal(err) }
 if string(got) != original { t.Fatalf("unparseable project settings replaced; error=%v; bytes=%s", enableErr, got) }
 if enableErr == nil { t.Fatal("enable accepted unparseable settings") }
}

func TestAuditInteractiveExternalGrant(t *testing.T) {
 setupTestRepo(t)
 t.Setenv("ENTIRE_TEST_CLAUDE_PROJECT_DIR", t.TempDir())
 writeSettings(t, `{"enabled":true}`)
 bin := t.TempDir()
 writeExternalAgentBinary(t, bin, "audit-grant")
 t.Setenv("PATH", bin+string(os.PathListSeparator)+os.Getenv("PATH"))
 if err := external.DiscoverAndRegisterNamedAlways(t.Context(), types.AgentName("audit-grant")); err != nil { t.Fatal(err) }
 ag, err := agent.Get(types.AgentName("audit-grant")); if err != nil { t.Fatal(err) }
 var out bytes.Buffer
 if err := runEnableInteractive(t.Context(), &out, []agent.Agent{ag}, EnableOptions{Yes:true, UseLocalSettings:true}); err != nil { t.Fatal(err) }
 got, err := settings.Load(t.Context()); if err != nil { t.Fatal(err) }
 if !got.ExternalAgents { data, _ := os.ReadFile(EntireSettingsLocalFile); t.Fatalf("external grant disappeared before enable returned; local=%s; output=%s", data, out.String()) }
}

func TestAuditEnableCancellation(t *testing.T) {
 setupTestRepo(t)
 t.Setenv("ENTIRE_TEST_CLAUDE_PROJECT_DIR", t.TempDir())
 ctx, cancel := context.WithCancel(t.Context()); defer cancel()
 withImportSeams(t, func(context.Context, []agent.Agent, string) []eligibleImport { return []eligibleImport{{displayName:"Claude Code",sessionCount:1}} }, nil,
 func(context.Context, io.Writer, string, []eligibleImport) { cancel() })
 ag, err := agent.Get(types.AgentName("claude-code")); if err != nil { t.Fatal(err) }
 var out bytes.Buffer
 err = runEnableInteractive(ctx, &out, []agent.Agent{ag}, EnableOptions{Yes:true, ImportHistory:true})
 if !errors.Is(err, context.Canceled) || strings.Contains(out.String(), "Ready.") { t.Fatalf("cancellation lost: err=%v, ctx=%v, output=%s", err, ctx.Err(), out.String()) }
}

func TestAuditAdoptTwice(t *testing.T) {
 source, middle, target := setupAdoptRepo(t), setupAdoptRepo(t), setupAdoptRepo(t)
 t.Setenv("ENTIRE_TEST_CLAUDE_PROJECT_DIR", "")
 ag, err := agent.Get(types.AgentName("claude-code")); if err != nil { t.Fatal(err) }
 dir, err := ag.GetSessionDir(source); if err != nil { t.Fatal(err) }
 sessionID := "audit-adopt-twice"
 transcript := ag.ResolveSessionFile(dir, sessionID)
 state := &session.State{SessionID:sessionID, AgentType:ag.Type(), StartedAt:time.Now(), Phase:session.PhaseActive, BaseCommit:testutil.GetHeadHash(t, source), WorktreePath:source, TranscriptPath:transcript}
 store := session.NewStateStoreWithDir(filepath.Join(source,".git",session.SessionStateDirName))
 if err := store.Save(t.Context(),state); err != nil { t.Fatal(err) }
 t.Chdir(middle); paths.ClearWorktreeRootCache(); session.ClearGitCommonDirCache()
 if err := runAdopt(t.Context(),io.Discard,sessionID,adoptOptions{FromWorktree:source,Force:true}); err != nil { t.Fatalf("first adoption: %v",err) }
 t.Chdir(target); paths.ClearWorktreeRootCache(); session.ClearGitCommonDirCache()
 if err := runAdopt(t.Context(),io.Discard,sessionID,adoptOptions{FromWorktree:middle,Force:true}); err != nil { t.Fatalf("second adoption rejected: %v",err) }
}

