func TestTrailAuditPatchPreservesTrailingSpaces(t *testing.T) {
 dir := t.TempDir()
 testutil.InitRepo(t, dir)
 t.Chdir(dir)
 testutil.WriteFile(t, dir, "text.md", "before\n")
 patch := "diff --git a/text.md b/text.md\n--- a/text.md\n+++ b/text.md\n@@ -1 +1 @@\n-before\n+after  \n"
 if err := runGitApply(t.Context(), patch, false); err != nil { t.Fatal(err) }
 got, err := os.ReadFile(filepath.Join(dir,"text.md")); if err != nil { t.Fatal(err) }
 if string(got) != "after  \n" { t.Fatalf("negative control: raw git did not preserve spaces: %q",got) }
 testutil.WriteFile(t, dir, "text.md", "before\n")
 comment := api.TrailReviewComment{ID:"space-fix",SuggestedChanges:[]api.TrailReviewSuggestedChange{{ID:"suggestion",ChangeType:"unified_diff",Patch:&patch}}}
 applied, err := applyTrailReviewSuggestions(t.Context(), comment, false, io.Discard)
 if err != nil { t.Fatal(err) }
 if applied != 1 { t.Fatalf("applied=%d",applied) }
 got, err = os.ReadFile(filepath.Join(dir,"text.md")); if err != nil { t.Fatal(err) }
 if string(got) != "after  \n" { t.Fatalf("trail apply changed suggested bytes: got %q; want %q",got,"after  \n") }
}

